from cs_lib import *
C = 'Precalculus'

sheet('precalculus-equations-inequalities', C, 1, 'Equations and Inequalities',
  'linear, absolute value and quadratic equations', 'polynomial, rational and radical equations and inequalities',
  [EX('Linear Equations', 'Distribute, collect variable terms, then isolate.', '4(x − 3) = 2x + 10', [['Distribute:', '4x − 12 = 2x + 10'], ['Collect:', '2x = 22']], 'x = 11', N('4*(11-3)-(2*11+10)', 0)),
   EX('Absolute Value Equations', 'Isolate the absolute value, then split into two cases.', '|2x − 5| = 9', [['Cases:', '2x − 5 = 9 or 2x − 5 = −9']], 'x = 7 or x = −2', [N('Math.abs(2*7-5)', 9), N('Math.abs(2*(-2)-5)', 9)]),
   EX('Absolute Value Inequalities', '|u| < a → −a < u < a. |u| > a → u < −a or u > a.', '|x + 1| ≤ 4', [['Compound:', '−4 ≤ x + 1 ≤ 4']], '−5 ≤ x ≤ 3', TRUE('Math.abs(-5+1)<=4 && Math.abs(3+1)<=4 && Math.abs(3.1+1)>4')),
   EX('Quadratic Formula', r'⟨x = \tfrac{-b \pm \sqrt{b^2 - 4ac}}{2a}⟩', r'⟨2x^2 - 3x - 5 = 0⟩', [['Discriminant:', '9 + 40 = 49'], ['Roots:', r'⟨\tfrac{3 \pm 7}{4}⟩']], r'⟨x = \tfrac{5}{2}⟩ or x = −1', [N('2*2.5**2-3*2.5-5', 0), N('2*1+3-5', 0)]),
   TB('The Discriminant', [r'⟨b^2 - 4ac⟩', 'Roots'], [['> 0', 'two real'], ['= 0', 'one real (double)'], ['< 0', 'two complex conjugates']]),
   MS('Quick Reminders & Common Mistakes', ['Isolate |…| before splitting into cases.', 'Set quadratics equal to 0 before factoring.', 'Check solutions in the original equation.'],
      [['|x − 3| = −2 has solutions', 'no solution'], ['|u| > a written as −a < u < a', 'two separate rays'], ['Dividing both sides by x', 'factor instead: you lose x = 0']])],
  [EX('Polynomial Equations', 'Factor completely and use the zero-product property.', r'⟨x^3 - 4x^2 - 5x = 0⟩', [['Factor:', 'x(x − 5)(x + 1) = 0']], 'x = 0, 5, −1', [N('125-100-25', 0), N('-1-4+5', 0)]),
   EX('Polynomial Inequalities', 'Find zeros, test each interval with a sign chart.', r'⟨x^2 - x - 6 > 0⟩', [['Zeros:', '(x − 3)(x + 2): −2 and 3'], ['Signs:', '+ | − | +']], 'x < −2 or x > 3', TRUE('(-3)**2+3-6>0 && !(0-0-6>0) && 16-4-6>0')),
   EX('Rational Equations', 'Multiply by the LCD; reject values that make a denominator 0.', r'⟨\tfrac{3}{x - 2} = \tfrac{x}{x - 2} - 1⟩', [['Multiply by x − 2:', '3 = x − (x − 2) = 2 ✗']], 'No solution', TRUE('3 !== 2')),
   EX('Rational Inequalities', 'Critical points: zeros of the top AND bottom. The bottom’s zeros are never included.', r'⟨\tfrac{x - 1}{x + 3} \le 0⟩', [['Critical:', '1 and −3'], ['Signs:', '+ | − | +']], '−3 < x ≤ 1', TRUE('(0-1)/(0+3)<=0 && (1-1)/(1+3)<=0 && (-4-1)/(-4+3)>0')),
   EX('Radical Equations', 'Isolate the radical, square both sides, CHECK for extraneous roots.', r'⟨\sqrt{x + 7} = x + 1⟩', [['Square:', r'⟨x + 7 = x^2 + 2x + 1⟩'], ['Factor:', '(x + 3)(x − 2) = 0']], 'x = 2 (x = −3 is extraneous)', [N('Math.sqrt(2+7)-(2+1)', 0), TRUE('Math.sqrt(-3+7) !== -3+1')]),
   L('Check Yourself', ['Did I check every root in the original equation?', 'Did I exclude zeros of the denominator?', 'Did I test every interval on my sign chart?', 'Did I flip the inequality when multiplying by a negative?'])])

sheet('precalculus-functions', C, 2, 'Functions',
  'domain, range, graphs and transformations', 'combinations, inverses, polynomial, rational, exponential and logarithmic functions',
  [V('Key Vocabulary', [['domain', 'All allowed inputs.', r'⟨\sqrt{x - 2}⟩: x ≥ 2'], ['range', 'All outputs.', r'⟨x^2⟩: y ≥ 0'], ['even function', 'f(−x) = f(x); y-axis symmetry.', r'⟨x^2⟩, cos x'], ['odd function', 'f(−x) = −f(x); origin symmetry.', r'⟨x^3⟩, sin x']]),
   TB('Transformations of f(x)', ['Form', 'Effect'], [['f(x) + k', 'up k'], ['f(x − h)', 'right h'], ['−f(x)', 'reflect over x-axis'], ['f(−x)', 'reflect over y-axis'], ['a·f(x)', 'vertical stretch by a'], ['f(bx)', r'horizontal shrink by ⟨\tfrac{1}{b}⟩']]),
   EX('Composition', '(f ∘ g)(x) = f(g(x)): inside first.', r'⟨f(x) = x^2 + 1,\ g(x) = 3x - 2⟩; find (f ∘ g)(2).', [['Inside:', 'g(2) = 4'], ['Outside:', 'f(4) = 17']], '17', N('(3*2-2)**2+1', 17)),
   EX('Inverse Functions', 'Swap x and y, then solve for y.', r'⟨f(x) = \tfrac{2x + 1}{3}⟩', [['Swap:', '3x = 2y + 1']], r'⟨f^{-1}(x) = \tfrac{3x - 1}{2}⟩', N('(3*((2*5+1)/3)-1)/2', 5)),
   EX('Average Rate of Change', r'⟨\tfrac{f(b) - f(a)}{b - a}⟩', r'⟨f(x) = x^3⟩ on [1, 3]', [['Compute:', r'⟨\tfrac{27 - 1}{2}⟩']], '13', N('(27-1)/2', 13)),
   MS('Quick Reminders & Common Mistakes', ['f(x − h) moves RIGHT, not left.', r'⟨f^{-1}(x) \ne \tfrac{1}{f(x)}⟩.', 'Only one-to-one functions have inverses.'],
      [['(f ∘ g)(x) = f(x) · g(x)', 'plug g into f'], ['f(x + 3) shifts right 3', 'left 3'], ['Domain of ⟨\\tfrac{1}{x - 4}⟩ is all reals', 'x ≠ 4']])],
  [TB('Polynomial End Behavior', ['Degree · lead coefficient', 'Ends'], [['even · positive', 'both up'], ['even · negative', 'both down'], ['odd · positive', 'down left, up right'], ['odd · negative', 'up left, down right']], 'A degree-n polynomial has at most n − 1 turning points.'),
   TB('Rational Function Asymptotes', ['Compare degrees n (top), d (bottom)', 'Horizontal asymptote'], [['n < d', 'y = 0'], ['n = d', 'y = ratio of leading coefficients'], ['n = d + 1', 'slant asymptote']], r'Vertical asymptotes: zeros of the reduced denominator. For ⟨\tfrac{2x + 1}{x - 3}⟩: x = 3, y = 2.'),
   TB('Log Properties', ['Property', 'Rule'], [['Product', r'⟨\log_b(MN) = \log_b M + \log_b N⟩'], ['Quotient', r'⟨\log_b \tfrac{M}{N} = \log_b M - \log_b N⟩'], ['Power', r'⟨\log_b M^p = p\log_b M⟩'], ['Change of base', r'⟨\log_b M = \tfrac{\ln M}{\ln b}⟩']], None, N('Math.log(8)/Math.log(2)', 3)),
   EX('Exponential Equations', 'Match bases, or take a log of both sides.', r'⟨5^{x - 1} = 125⟩', [['Match bases:', r'⟨5^{x - 1} = 5^3⟩']], 'x = 4', N('5**(4-1)', 125)),
   EX('Logarithmic Equations', 'Rewrite in exponential form; check the domain.', r'⟨\log_2(x + 3) = 5⟩', [['Exponential form:', r'⟨x + 3 = 2^5⟩']], 'x = 29', N('Math.log2(29+3)', 5)),
   EX('Exponential Growth Model', r'⟨A = Pe^{rt}⟩ for continuous growth.', '$2,000 at 4% compounded continuously for 5 years', [['Compute:', r'⟨2000e^{0.2}⟩']], '≈ $2,442.81', N('Math.round(2000*Math.exp(0.2)*100)/100', 2442.81))])

sheet('precalculus-conics', C, 3, 'Conics',
  'parabolas and circles', 'ellipses, hyperbolas and identifying conics',
  [TB('Parabolas', ['Form', 'Opens · focus'], [[r'⟨(x - h)^2 = 4p(y - k)⟩', 'up/down · (h, k + p)'], [r'⟨(y - k)^2 = 4p(x - h)⟩', 'right/left · (h + p, k)']], 'Vertex (h, k). The directrix is p units on the other side of the vertex.'),
   EX('Parabola Focus and Directrix', 'Match 4p, then move p from the vertex.', r'⟨x^2 = 12y⟩', [['4p = 12:', 'p = 3']], 'focus (0, 3), directrix y = −3', N('12/4', 3)),
   TB('Circles', ['Form', 'Gives'], [[r'⟨(x - h)^2 + (y - k)^2 = r^2⟩', 'center (h, k), radius r']]),
   EX('Complete the Square', 'Group x’s and y’s, add the square of half each coefficient to both sides.', r'⟨x^2 + y^2 - 6x + 4y - 12 = 0⟩', [['Group:', r'⟨(x^2 - 6x + 9) + (y^2 + 4y + 4) = 12 + 9 + 4⟩']], r'center (3, −2), r = 5', N('Math.sqrt(12+9+4)', 5)),
   V('Key Vocabulary', [['focus', 'Fixed point used to define a conic.', 'parabola: (0, p)'], ['directrix', 'Fixed line for a parabola.', 'y = −p'], ['vertex', 'Turning point / end of the major axis.', '(h, k)'], ['eccentricity', r'⟨e = \tfrac{c}{a}⟩: how stretched.', 'circle e = 0']]),
   MS('Quick Reminders & Common Mistakes', ['Signs inside the parentheses are opposite the center.', 'Add the same amounts to BOTH sides when completing the square.', 'r is the square root of the right side.'],
      [['(x + 3)² → center x = 3', 'x = −3'], ['Radius = 25', r'⟨r = \sqrt{25} = 5⟩'], ['Forgetting to add to the right side', 'balance both sides']])],
  [TB('Ellipses', ['Form', 'Key facts'], [[r'⟨\tfrac{(x - h)^2}{a^2} + \tfrac{(y - k)^2}{b^2} = 1⟩', 'a > b: horizontal major axis'], ['Foci', r'⟨c^2 = a^2 - b^2⟩'], ['Lengths', 'major axis 2a, minor axis 2b']]),
   EX('Ellipse Foci', 'Find c from a and b.', r'⟨\tfrac{x^2}{25} + \tfrac{y^2}{9} = 1⟩', [['c² = 25 − 9 = 16:', 'c = 4']], 'foci (±4, 0), vertices (±5, 0)', N('Math.sqrt(25-9)', 4)),
   TB('Hyperbolas', ['Form', 'Key facts'], [[r'⟨\tfrac{(x - h)^2}{a^2} - \tfrac{(y - k)^2}{b^2} = 1⟩', 'opens left/right'], ['Foci', r'⟨c^2 = a^2 + b^2⟩'], ['Asymptotes', r'⟨y - k = \pm\tfrac{b}{a}(x - h)⟩']]),
   EX('Hyperbola Facts', 'Positive term tells the direction.', r'⟨\tfrac{x^2}{9} - \tfrac{y^2}{16} = 1⟩', [['c² = 9 + 16 = 25:', 'c = 5']], r'foci (±5, 0), asymptotes ⟨y = \pm\tfrac{4}{3}x⟩', N('Math.sqrt(9+16)', 5)),
   TB('Identify the Conic', [r'⟨Ax^2 + Cy^2 + \dots = 0⟩', 'Conic'], [['A = C', 'circle'], ['A·C > 0, A ≠ C', 'ellipse'], ['A·C < 0', 'hyperbola'], ['A = 0 or C = 0', 'parabola']], r'⟨4x^2 - y^2 + 8x = 0⟩: A·C = −4 < 0 → hyperbola.'),
   L('Check Yourself', ['Ellipse: c² = a² − b². Hyperbola: c² = a² + b².', 'Is a under the larger (ellipse) or positive (hyperbola) term?', 'Did I complete the square on both variables?', 'Did I sketch to check my answer?'])])

sheet('precalculus-trigonometric-functions', C, 4, 'Trigonometric Functions',
  'angles, radians, the unit circle and graphs', 'inverse trig functions, identities and trig equations',
  [EX('Degrees and Radians', r'Multiply by ⟨\tfrac{\pi}{180}⟩ or ⟨\tfrac{180}{\pi}⟩.', r'Convert 150° and ⟨\tfrac{5\pi}{4}⟩.', [['150° · π ÷ 180:', r'⟨\tfrac{5\pi}{6}⟩']], r'⟨\tfrac{5\pi}{6}⟩ and 225°', [N('150*Math.PI/180', 5*3.141592653589793/6), N('5/4*180', 225)]),
   TB('Unit Circle Values', ['θ', 'cos θ · sin θ'], [['0', '1 · 0'], [r'⟨\tfrac{\pi}{6}⟩', r'⟨\tfrac{\sqrt{3}}{2}⟩ · ⟨\tfrac{1}{2}⟩'], [r'⟨\tfrac{\pi}{4}⟩', r'⟨\tfrac{\sqrt{2}}{2}⟩ · ⟨\tfrac{\sqrt{2}}{2}⟩'], [r'⟨\tfrac{\pi}{3}⟩', r'⟨\tfrac{1}{2}⟩ · ⟨\tfrac{\sqrt{3}}{2}⟩'], [r'⟨\tfrac{\pi}{2}⟩', '0 · 1']], 'ASTC: All, Sin, Tan, Cos positive in quadrants I–IV.', N('Math.sin(Math.PI/6)', 0.5)),
   EX('Reference Angles', 'Use the reference angle, then the quadrant sign.', r'⟨\cos\tfrac{2\pi}{3}⟩', [['Reference:', r'⟨\tfrac{\pi}{3}⟩, quadrant II (cos −)']], r'⟨-\tfrac{1}{2}⟩', N('Math.cos(2*Math.PI/3)', -0.5)),
   TB('Sinusoid Graphs', [r'⟨y = A\sin(B(x - C)) + D⟩', 'Meaning'], [['|A|', 'amplitude'], [r'⟨\tfrac{2\pi}{B}⟩', 'period'], ['C', 'phase shift'], ['D', 'midline y = D']], r'⟨y = 3\sin 2x - 1⟩: amplitude 3, period π, midline y = −1.'),
   EX('Arc Length and Sector Area', r'⟨s = r\theta⟩, ⟨A = \tfrac{1}{2}r^2\theta⟩ (θ in radians).', r'r = 6, ⟨\theta = \tfrac{\pi}{3}⟩', [['Arc:', r'⟨6 \cdot \tfrac{\pi}{3}⟩'], ['Area:', r'⟨\tfrac{1}{2}(36)\tfrac{\pi}{3}⟩']], r'⟨s = 2\pi⟩, ⟨A = 6\pi⟩', [N('6*Math.PI/3', 2*3.141592653589793), N('0.5*36*Math.PI/3', 6*3.141592653589793)]),
   MS('Quick Reminders & Common Mistakes', ['Check degree/radian mode.', r'tan θ = ⟨\tfrac{\sin\theta}{\cos\theta}⟩.', 'Period of tan is π, not 2π.'],
      [['Period of sin 2x = 4π', 'π'], ['s = rθ with θ in degrees', 'radians'], ['cos 120° = ½', '−½ (quadrant II)']])],
  [TB('Inverse Trig Ranges', ['Function', 'Range'], [[r'⟨\sin^{-1}x⟩', r'⟨[-\tfrac{\pi}{2}, \tfrac{\pi}{2}]⟩'], [r'⟨\cos^{-1}x⟩', '[0, π]'], [r'⟨\tan^{-1}x⟩', r'⟨(-\tfrac{\pi}{2}, \tfrac{\pi}{2})⟩']], r'⟨\cos^{-1}(-\tfrac{1}{2}) = \tfrac{2\pi}{3}⟩', N('Math.acos(-0.5)', 2*3.141592653589793/3)),
   TB('Fundamental Identities', ['Type', 'Identity'], [['Pythagorean', r'⟨\sin^2\theta + \cos^2\theta = 1⟩'], ['', r'⟨1 + \tan^2\theta = \sec^2\theta⟩'], ['Reciprocal', r'⟨\csc\theta = \tfrac{1}{\sin\theta}⟩, ⟨\sec\theta = \tfrac{1}{\cos\theta}⟩'], ['Even/odd', 'cos(−θ) = cos θ, sin(−θ) = −sin θ']], None, N('Math.sin(1)**2+Math.cos(1)**2', 1)),
   TB('Sum and Double-Angle', ['Formula', 'Expansion'], [['sin(A ± B)', 'sin A cos B ± cos A sin B'], ['cos(A ± B)', 'cos A cos B ∓ sin A sin B'], ['sin 2θ', '2 sin θ cos θ'], ['cos 2θ', r'⟨\cos^2\theta - \sin^2\theta = 1 - 2\sin^2\theta⟩']], None, N('Math.sin(2*0.7)-2*Math.sin(0.7)*Math.cos(0.7)', 0)),
   EX('Verifying an Identity', 'Work one side; rewrite in sines and cosines.', r'⟨\tan\theta\cos\theta = \sin\theta⟩', [['Rewrite:', r'⟨\tfrac{\sin\theta}{\cos\theta} \cdot \cos\theta⟩']], 'sin θ ✓', N('Math.tan(0.4)*Math.cos(0.4)-Math.sin(0.4)', 0)),
   EX('Solving Trig Equations', 'Isolate the trig function; find ALL solutions in [0, 2π).', r'⟨2\sin\theta - 1 = 0⟩', [['sin θ = ½:', 'quadrants I and II']], r'⟨\theta = \tfrac{\pi}{6}, \tfrac{5\pi}{6}⟩', [N('2*Math.sin(Math.PI/6)-1', 0), N('2*Math.sin(5*Math.PI/6)-1', 0)]),
   L('Check Yourself', ['Did I find every solution in the interval?', 'Is my inverse-trig answer in the right range?', 'Did I keep θ in radians where needed?', 'Did I avoid dividing by a trig function (losing solutions)?'])])

sheet('precalculus-general-triangle-trigonometry', C, 5, 'Trigonometry of General Triangles',
  'right-triangle trig and the Law of Sines', 'the Law of Cosines, the ambiguous case and triangle area',
  [TB('Right-Triangle Ratios', ['Ratio', 'Definition'], [['sin θ', r'⟨\tfrac{\text{opp}}{\text{hyp}}⟩'], ['cos θ', r'⟨\tfrac{\text{adj}}{\text{hyp}}⟩'], ['tan θ', r'⟨\tfrac{\text{opp}}{\text{adj}}⟩']]),
   EX('Solving a Right Triangle', 'Pick the ratio connecting the known side to the unknown.', 'Angle 35°, hypotenuse 12. Opposite side?', [['sin 35° = x ÷ 12:', 'x = 12 sin 35°']], '≈ 6.88', N('Math.round(12*Math.sin(35*Math.PI/180)*100)/100', 6.88)),
   TB('The Law of Sines', ['Use when you know', 'Formula'], [['AAS or ASA', r'⟨\tfrac{a}{\sin A} = \tfrac{b}{\sin B} = \tfrac{c}{\sin C}⟩'], ['SSA (ambiguous)', 'check for 0, 1 or 2 triangles']]),
   EX('Law of Sines (AAS)', 'Find the third angle, then use the ratio.', 'A = 40°, B = 60°, a = 10. Find b.', [['Ratio:', r'⟨b = \tfrac{10\sin 60°}{\sin 40°}⟩']], '≈ 13.47', N('Math.round(10*Math.sin(Math.PI/3)/Math.sin(40*Math.PI/180)*100)/100', 13.47)),
   W('Angles of Elevation and Depression', [['Elevation', 'measured UP from the horizontal'], ['Depression', 'measured DOWN from the horizontal'], ['They are equal', 'alternate interior angles']]),
   MS('Quick Reminders & Common Mistakes', ['Side a is opposite angle A.', 'Angles in a triangle sum to 180°.', 'Keep full precision until the end.'],
      [['Using sine law with SAS', 'use the Law of Cosines'], ['Calculator in radian mode', 'degree mode'], ['Rounding early', 'round at the end']])],
  [TB('The Law of Cosines', ['Use when you know', 'Formula'], [['SAS', r'⟨c^2 = a^2 + b^2 - 2ab\cos C⟩'], ['SSS', r'⟨\cos C = \tfrac{a^2 + b^2 - c^2}{2ab}⟩']]),
   EX('Law of Cosines (SAS)', 'Use the included angle.', 'a = 7, b = 9, C = 50°. Find c.', [['Compute:', r'⟨49 + 81 - 126\cos 50°⟩']], '≈ 7.00', N('Math.round(Math.sqrt(49+81-126*Math.cos(50*Math.PI/180))*100)/100', 7.0)),
   EX('Law of Cosines (SSS)', 'Find the largest angle first (opposite the longest side).', 'a = 5, b = 7, c = 8. Find C.', [['cos C:', r'⟨\tfrac{25 + 49 - 64}{70} = \tfrac{1}{7}⟩']], '≈ 81.8°', N('Math.round(Math.acos(1/7)*180/Math.PI*10)/10', 81.8)),
   TB('The Ambiguous Case (SSA, A acute)', ['Condition', 'Triangles'], [['a < b sin A', '0'], ['a = b sin A', '1 (right)'], ['b sin A < a < b', '2'], ['a ≥ b', '1']]),
   TB('Triangle Area', ['Given', 'Area'], [['two sides + included angle', r'⟨\tfrac{1}{2}ab\sin C⟩'], ['three sides (Heron)', r'⟨\sqrt{s(s - a)(s - b)(s - c)}⟩, ⟨s = \tfrac{a + b + c}{2}⟩']], 'Sides 5, 7, 8: s = 10, area = √300 ≈ 17.32.', N('Math.sqrt(10*5*3*2)', 17.320508075688775)),
   L('Check Yourself', ['SAS / SSS → Law of Cosines; AAS / ASA → Law of Sines.', 'For SSA, did I check for a second triangle?', 'Is the longest side opposite the largest angle?', 'Do my angles add to 180°?'])])

sheet('precalculus-matrices', C, 6, 'Matrices',
  'matrix operations and multiplication', 'determinants, inverses and solving systems',
  [V('Key Vocabulary', [['dimensions', 'rows × columns.', '2 × 3 matrix'], ['identity matrix', '1s on the diagonal, 0s elsewhere.', 'AI = A'], ['scalar', 'A single number multiplying every entry.', '3A'], ['square matrix', 'Same rows and columns.', '2 × 2']]),
   EX('Adding and Scalar Multiplication', 'Add matching entries. A scalar multiplies every entry.', r'⟨2\begin{bmatrix}1 & -3\\ 4 & 0\end{bmatrix} + \begin{bmatrix}2 & 5\\ -1 & 6\end{bmatrix}⟩', [['Scale:', r'⟨\begin{bmatrix}2 & -6\\ 8 & 0\end{bmatrix}⟩']], r'⟨\begin{bmatrix}4 & -1\\ 7 & 6\end{bmatrix}⟩', [N('2*1+2', 4), N('2*(-3)+5', -1)]),
   EX('Matrix Multiplication', 'Row of the first times column of the second. Inner dimensions must match.', r'⟨\begin{bmatrix}1 & 2\\ 3 & 4\end{bmatrix}\begin{bmatrix}5\\ 6\end{bmatrix}⟩', [['Row 1:', '1·5 + 2·6 = 17'], ['Row 2:', '3·5 + 4·6 = 39']], r'⟨\begin{bmatrix}17\\ 39\end{bmatrix}⟩', [N('1*5+2*6', 17), N('3*5+4*6', 39)]),
   TB('When Can You Multiply?', ['A × B', 'Result'], [['(2 × 3)(3 × 4)', '2 × 4'], ['(3 × 2)(3 × 2)', 'undefined'], ['(1 × 3)(3 × 1)', '1 × 1']], 'Matrix multiplication is NOT commutative: AB ≠ BA in general.'),
   W('Matrices in Context', [['Inventory × prices', 'total cost per store'], ['Transformation matrix', 'rotates or reflects points'], ['Adjacency matrix', 'connections in a network']]),
   MS('Quick Reminders & Common Mistakes', ['Write dimensions before multiplying.', 'Add only matrices of the same size.', 'Order matters in multiplication.'],
      [['Multiplying entry by entry', 'row × column'], ['AB = BA', 'usually not'], ['Adding a 2 × 2 to a 2 × 3', 'undefined']])],
  [EX('2 × 2 Determinant', r'⟨\det\begin{bmatrix}a & b\\ c & d\end{bmatrix} = ad - bc⟩', r'⟨\begin{bmatrix}4 & 3\\ 2 & 5\end{bmatrix}⟩', [['ad − bc:', '20 − 6']], '14', N('4*5-3*2', 14)),
   EX('2 × 2 Inverse', r'⟨A^{-1} = \tfrac{1}{ad - bc}\begin{bmatrix}d & -b\\ -c & a\end{bmatrix}⟩', r'⟨\begin{bmatrix}4 & 3\\ 2 & 5\end{bmatrix}⟩', [['Swap a and d, negate b and c:', 'divide by det = 14']], r'⟨\tfrac{1}{14}\begin{bmatrix}5 & -3\\ -2 & 4\end{bmatrix}⟩', N('(4*5+3*(-2))/14', 1)),
   EX('Solving AX = B', r'⟨X = A^{-1}B⟩ (multiply on the LEFT).', '4x + 3y = 10, 2x + 5y = 12', [['Multiply:', r'⟨\tfrac{1}{14}(5 \cdot 10 - 3 \cdot 12,\ -2 \cdot 10 + 4 \cdot 12)⟩']], 'x = 1, y = 2', [N('4*1+3*2', 10), N('2*1+5*2', 12)]),
   TB('3 × 3 Determinant (expand row 1)', ['Term', 'Sign'], [[r'⟨a_{11}\cdot\text{minor}_{11}⟩', '+'], [r'⟨a_{12}\cdot\text{minor}_{12}⟩', '−'], [r'⟨a_{13}\cdot\text{minor}_{13}⟩', '+']], 'If det = 0, the matrix has no inverse (singular).'),
   EX('Cramer’s Rule', r'⟨x = \tfrac{\det A_x}{\det A}⟩: replace the x-column with the constants.', '4x + 3y = 10, 2x + 5y = 12', [['det A_x:', '10·5 − 3·12 = 14']], r'⟨x = \tfrac{14}{14} = 1⟩', N('(10*5-3*12)/14', 1)),
   L('Check Yourself', ['Is det ≠ 0 before I invert?', 'Did I multiply A⁻¹ on the LEFT of B?', 'Did I check my solution in the original system?', 'Do the dimensions allow this product?'])])

sheet('precalculus-vectors', C, 7, 'Vectors',
  'vector components, magnitude, direction and operations', 'dot product, angles between vectors, projections and applications',
  [V('Key Vocabulary', [['vector', 'Has magnitude and direction.', '⟨3, 4⟩'], ['magnitude', 'Length of the vector.', r'⟨\|\langle 3, 4\rangle\| = 5⟩'], ['unit vector', 'Magnitude 1.', r'⟨\langle \tfrac{3}{5}, \tfrac{4}{5}\rangle⟩'], ['resultant', 'The sum of vectors.', 'u + v']]),
   EX('Component Form', 'Terminal point minus initial point.', 'From P(1, −2) to Q(6, 10)', [['Subtract:', '⟨6 − 1, 10 − (−2)⟩']], '⟨5, 12⟩, magnitude 13', N('Math.hypot(5,12)', 13)),
   EX('Magnitude and Direction', r'⟨\|v\| = \sqrt{a^2 + b^2}⟩, ⟨\tan\theta = \tfrac{b}{a}⟩ (check the quadrant).', 'v = ⟨−3, 3⟩', [['Magnitude:', r'⟨\sqrt{18} = 3\sqrt{2}⟩'], ['Direction:', 'quadrant II']], r'⟨3\sqrt{2}⟩, 135°', [N('Math.hypot(-3,3)', 3*1.4142135623730951), N('Math.atan2(3,-3)*180/Math.PI', 135)]),
   EX('Vector Operations', 'Add or scale component by component.', 'u = ⟨2, −1⟩, v = ⟨−4, 3⟩. Find 3u − v.', [['3u:', '⟨6, −3⟩'], ['Subtract v:', '⟨6 + 4, −3 − 3⟩']], '⟨10, −6⟩', [N('3*2-(-4)', 10), N('3*(-1)-3', -6)]),
   EX('Vector from Magnitude and Angle', r'⟨v = \langle \|v\|\cos\theta, \|v\|\sin\theta \rangle⟩', '|v| = 10 at 30°', [['Components:', '⟨10 cos 30°, 10 sin 30°⟩']], r'⟨\langle 5\sqrt{3}, 5 \rangle⟩', N('10*Math.sin(Math.PI/6)', 5)),
   MS('Quick Reminders & Common Mistakes', ['Component form = terminal − initial.', 'Use atan2 thinking: check the quadrant.', 'Magnitude is never negative.'],
      [['Initial − terminal', 'terminal − initial'], ['tan⁻¹(3 ÷ −3) = −45°', '135° (quadrant II)'], ['|u + v| = |u| + |v|', 'only if parallel']])],
  [EX('Dot Product', r'⟨u \cdot v = u_1v_1 + u_2v_2⟩ (a number).', 'u = ⟨3, 4⟩, v = ⟨2, −1⟩', [['Multiply and add:', '6 − 4']], '2', N('3*2+4*(-1)', 2)),
   EX('Angle Between Vectors', r'⟨\cos\theta = \tfrac{u \cdot v}{\|u\|\|v\|}⟩', 'u = ⟨1, 0⟩, v = ⟨1, 1⟩', [['cos θ:', r'⟨\tfrac{1}{1 \cdot \sqrt{2}}⟩']], '45°', N('Math.acos(1/Math.SQRT2)*180/Math.PI', 45)),
   TB('Orthogonal and Parallel', ['Test', 'Meaning'], [['u · v = 0', 'orthogonal (perpendicular)'], ['u = kv', 'parallel'], ['u · v > 0', 'angle < 90°']], '⟨2, 3⟩ · ⟨−3, 2⟩ = 0, so they are orthogonal.', N('2*(-3)+3*2', 0)),
   EX('Projection', r'⟨\text{proj}_v u = \tfrac{u \cdot v}{\|v\|^2}v⟩', 'u = ⟨4, 2⟩ onto v = ⟨3, 0⟩', [['Scalar:', r'⟨\tfrac{12}{9} = \tfrac{4}{3}⟩']], '⟨4, 0⟩', N('12/9*3', 4)),
   EX('Work', r'W = F · d = ⟨\|F\|\|d\|\cos\theta⟩', 'A 50 N force at 60° moves a box 10 m.', [['Compute:', '50 · 10 · cos 60°']], '250 J', N('50*10*Math.cos(Math.PI/3)', 250)),
   L('Check Yourself', ['The dot product is a NUMBER, not a vector.', 'Did I divide by |v|² for the projection?', 'Are my angles in the right quadrant?', 'Did I sketch the vectors?'])])

sheet('precalculus-probability', C, 8, 'Probability',
  'counting, permutations, combinations and basic probability', 'conditional probability, independence, the binomial theorem and expected value',
  [EX('Fundamental Counting Principle', 'Multiply the number of choices at each stage.', 'A code: 2 letters then 3 digits', [['Multiply:', r'⟨26^2 \cdot 10^3⟩']], '676,000', N('26**2*1000', 676000)),
   TB('Permutations and Combinations', ['Type', 'Formula'], [['Permutation (order matters)', r'⟨_nP_r = \tfrac{n!}{(n - r)!}⟩'], ['Combination (order does not)', r'⟨_nC_r = \tfrac{n!}{r!(n - r)!}⟩'], ['Repeated letters', r'⟨\tfrac{n!}{n_1!\,n_2!\cdots}⟩']]),
   EX('Permutations', 'Order matters: president, VP, treasurer.', 'Choose 3 officers from 10 people.', [['Compute:', '10 · 9 · 8']], '720', N('10*9*8', 720)),
   EX('Combinations', 'Order does not matter: a committee.', 'Choose a 3-person committee from 10.', [['Divide by 3!:', r'⟨\tfrac{720}{6}⟩']], '120', N('720/6', 120)),
   TB('Probability Rules', ['Rule', 'Formula'], [['Complement', "P(A') = 1 − P(A)"], ['Addition', 'P(A or B) = P(A) + P(B) − P(A and B)'], ['Mutually exclusive', 'P(A and B) = 0']], 'Draw a card: P(heart or king) = 13/52 + 4/52 − 1/52 = 16/52.', N('(13+4-1)/52', 16/52)),
   MS('Quick Reminders & Common Mistakes', ['Ask: does order matter?', '0! = 1.', 'Probabilities are between 0 and 1.'],
      [['Using P for a committee', 'C (order does not matter)'], ['P(A or B) = P(A) + P(B) always', 'subtract the overlap'], ['P(at least one) by listing all cases', '1 − P(none)']])],
  [EX('Conditional Probability', r'⟨P(A \mid B) = \tfrac{P(A \text{ and } B)}{P(B)}⟩', 'P(B) = 0.5, P(A and B) = 0.2', [['Divide:', r'⟨\tfrac{0.2}{0.5}⟩']], '0.4', N('0.2/0.5', 0.4)),
   EX('Independent Events', 'A and B independent ⇔ P(A and B) = P(A)P(B).', 'P(A) = 0.3, P(B) = 0.6, P(A and B) = 0.18', [['Check:', '0.3 · 0.6 = 0.18 ✓']], 'Independent', TRUE('Math.abs(0.3*0.6-0.18)<1e-12')),
   EX('At Least One', 'Use the complement.', 'P(at least one 6 in 3 rolls)', [['Complement:', r'⟨1 - (\tfrac{5}{6})^3⟩']], r'⟨\tfrac{91}{216}⟩ ≈ 0.421', N('1-(5/6)**3', 91/216)),
   EX('Binomial Probability', r'⟨P(X = k) = {_nC_k}\,p^k(1 - p)^{n - k}⟩', 'Exactly 2 heads in 5 fair flips', [['Compute:', r'⟨10 \cdot (\tfrac{1}{2})^5⟩']], r'⟨\tfrac{10}{32} = \tfrac{5}{16}⟩', N('10*0.5**5', 5/16)),
   EX('Binomial Theorem', r'Term k + 1 of ⟨(a + b)^n⟩: ⟨_nC_k\,a^{n - k}b^k⟩', r'Coefficient of ⟨x^2⟩ in ⟨(x + 3)^4⟩', [['k = 2:', r'⟨_4C_2 \cdot 3^2 = 6 \cdot 9⟩']], '54', N('6*9', 54)),
   EX('Expected Value', 'E(X) = Σ x · P(x).', 'Win $10 with P = 0.2, lose $3 with P = 0.8.', [['Compute:', '10(0.2) + (−3)(0.8)']], '−$0.40 per play', N('10*0.2-3*0.8', -0.4))])
